  if (/quiet|peace|garden|park|walk|nature|green|calm/.test(s)) return 'nature';
  if (/cosy|cozy|coffee|cafe|café|book|social|brunch/.test(s)) return 'cosy';
  if (/unusual|quirky|unexpected|market|fun/.test(s)) return 'unusual';
