  const get=id=>catalog.find(p=>p.id===id);
  if(state.flow==='rainy') return [get('nhm'),get('design-museum'),get('va-cafe')].filter(Boolean);
  if(state.flow==='coffee') return catalog.filter(isCafe).sort((a,b)=>(b.reviews||0)-(a.reviews||0)).slice(0,3);
