function transportCost(){return ({walk:{amount:0,label:'Walk from stop to stop'},bus:{amount:3.5,label:'Bus return · adult estimate'},tube:{amount:6.2,label:'Zone 1 Tube return · adult estimate'}}[state.travelMode])}
function dayBudget(stops=state.walk.length?state.walk:flowStops()){const fares=transportCost(),items=stops.map((place,index)=>({place,time:['10:00','12:30','15:00','17:00'][Math.min(index,3)],cost:itemCost(place)})),known=items.filter(x=>x.cost.low!==null),low=fares.amount+known.reduce((sum,x)=>sum+x.cost.low,0),high=fares.amount+known.reduce((sum,x)=>sum+x.cost.high,0);return{fares,items,low,high,unknown:items.length-known.length}}
