  if(p.mood===preferred)n+=4;
  if(state.saved.size && state.saved.has('kgardens') && p.tags?.includes('garden'))n+=1.2;
  if(state.saved.size && [...state.saved].some(id=>seeds.find(x=>x.id===id)?.mood===p.mood))n+=.6;
  if([...state.skipped].some(id=>allPlaces().find(x=>x.id===id)?.mood===p.mood))n-=1.5;
  if((state.query+' '+state.mood).match(/rain|rainy/i) && p.tags?.includes('indoor'))n+=2;
