function voiceSearch(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){alert('Voice search is not supported in this browser. Try typing your idea instead.');return}const rec=new SR();rec.lang='en-GB';rec.interimResults=false;const b=root.querySelector('#voice');b.classList.add('listening');rec.onresult=e=>{state.query=e.results[0][0].transcript;state.mood=queryMood(state.query)||state.mood;if(apiKey)loadLive().then(render);else render()};rec.onerror=()=>b.classList.remove('listening');rec.onend=()=>b.classList.remove('listening');rec.start()}
